import __manifest__


def _get_manifest():
    """Load the manifest dict from the module file."""
    with open(__manifest__.__file__) as f:
        return eval(f.read())


def test_data_is_list():
    manifest = _get_manifest()
    assert isinstance(manifest['data'], list)


def test_data_is_not_empty():
    manifest = _get_manifest()
    assert len(manifest['data']) > 0


def test_data_contains_view_file():
    manifest = _get_manifest()
    assert 'views/issue_analysis_views.xml' in manifest['data']


def test_manifest_name_unchanged():
    manifest = _get_manifest()
    assert manifest['name'] == 'AI Issue Analysis'


def test_demo_remains_empty():
    manifest = _get_manifest()
    assert manifest['demo'] == []
